﻿const ToolBar = utilscesium.Control.ToolBar;
Cesium.Ion.defaultAccessToken =
  "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJqdGkiOiJlNmZlMThiNC05MjZjLTRhMzQtYjk1NC04Mzk1OWUzNGQyNDYiLCJpZCI6MTE2NjEsInNjb3BlcyI6WyJhc2wiLCJhc3IiLCJhc3ciLCJnYyJdLCJpYXQiOjE1NTk1NTEwODh9.1sP9cG15Apatkf1x1g1_P_86wc3gFNOZM66XoWLUsxc";
var viewer = new Cesium.Viewer("map", {
  animation: false,
  homeButton: false,
  fullscreenButton: false,
  geocoder: false,
  sceneModePicker: false,
  baseLayerPicker: false,
  timeline: false,
  infoBox: false,
  navigationHelpButton: false,
  selectionIndicator: false,
  terrainProvider: null,
  imageryProvider: false,
  baseLayerPicker: false,
});

//全球影像地图服务
viewer.imageryLayers.addImageryProvider(
  new Cesium.WebMapTileServiceImageryProvider({
    url:
      "http://t0.tianditu.com/img_w/wmts?service=wmts&request=GetTile&version=1.0.0&LAYER=img&tileMatrixSet=w&TileMatrix={TileMatrix}&TileRow={TileRow}&TileCol={TileCol}&style=default&format=tiles&tk=6703c18da8b111f1ac38fdcfc4a138d8",
    layer: "tdtBasicLayer",
    style: "default",
    format: "image/jpeg",
    tileMatrixSetID: "GoogleMapsCompatible",
    show: false,
  })
);

//全球影像中文注记服务
viewer.imageryLayers.addImageryProvider(
  new Cesium.WebMapTileServiceImageryProvider({
    url:
      "http://t0.tianditu.com/cva_w/wmts?service=wmts&request=GetTile&version=1.0.0&LAYER=cva&tileMatrixSet=w&TileMatrix={TileMatrix}&TileRow={TileRow}&TileCol={TileCol}&style=default.jpg&tk=6703c18da8b111f1ac38fdcfc4a138d8",
    layer: "tdtAnnoLayer",
    style: "default",
    format: "image/jpeg",
    tileMatrixSetID: "GoogleMapsCompatible",
  })
);
//加载地形
viewer.terrainProvider = new Cesium.CesiumTerrainProvider({
  url: "http://hzgzsoft.com:5681/data/terrain/china/",
});
viewer.scene.globe.depthTestAgainstTerrain = true;

var view = {
  //destination: Cesium.Cartesian3.fromDegrees(120.3, 26, 300000),   //坐标点
  destination: Cesium.Rectangle.fromDegrees(
    119.05283765744,
    27.3397589411195,
    119.252892017179,
    27.3897617948041
  ),
  orientation: {
    heading: Cesium.Math.toRadians(0), //水平角度   //是当前方向 由北向东旋转的角度
    pitch: Cesium.Math.toRadians(-30), //俯视角度    //方向和水平平面的夹角,为正 表示方向向量指向水平平面上方，反之表示方向向量指向平面下方
    roll: 0, //是方向向量以正东方向为轴的旋转角度
  },
};
viewer.camera.setView(view);

var draw = new utilscesium.Draw.Rectangle();
draw.drawStart.addEventListener(function() {});
draw.drawEnd.addEventListener(function(event) {
  console.log(event);
  var rect = event.rect;
  viewer.entities.add({
    rectangle: {
      coordinates: rect,
      material: Cesium.Color.RED.withAlpha(0.4),
      outline: true,
      outlineWidth: 2,
      outlineColor: Cesium.Color.RED,
      heightReference: Cesium.HeightReference.CLAMP_TO_GROUND,
    },
  });
});
draw.setViewer(viewer);
draw.setActive(true);
